<script setup lang="ts">
import { computed, ref } from 'vue'
const asOf='2026-10-16'
const filter=ref('all')
const message=ref('Local sample records only.')
const items=ref([{id:'dental',title:'Dental checkup',due:'2026-09-19',completed:''},{id:'rabies',title:'Rabies booster',due:'2026-09-03',completed:'2026-09-03'},{id:'deworm',title:'Deworming',due:'2026-10-01',completed:'2026-10-01'},{id:'flea',title:'Flea and tick',due:'2026-10-16',completed:''},{id:'review',title:'Plan review',due:'2026-11-12',completed:''}])
type Item=typeof items.value[number]
function status(x:Item){return x.completed?'Done':x.due<asOf?'Overdue':x.due===asOf?'Due today':'Upcoming'}
const visible=computed(()=>items.value.filter(x=>filter.value==='all'||(filter.value==='open'?!x.completed:status(x)==='Overdue')).slice().sort((a,b)=>a.due.localeCompare(b.due)))
const completed=computed(()=>items.value.filter(x=>x.completed).length)
function toggle(x:Item){if(x.completed){x.completed='';message.value=x.title+': completion removed from local sample.'}else{x.completed=asOf;message.value=x.title+': marked done in local sample only.'}}
function reset(){items.value.forEach(x=>x.completed=x.id==='rabies'?'2026-09-03':x.id==='deworm'?'2026-10-01':'');filter.value='all';message.value='Sample reset. No care record was saved.'}
</script>
<template>
<section class="care-timeline-demo" aria-label="Local care timeline example"><h3>Sample pet's care</h3><p>Fictitious records. Status is evaluated as of <time :datetime="asOf">{{ asOf }}</time>, not today's date. No medical advice, reminders or booking.</p><label>Show records<select v-model="filter"><option value="all">All</option><option value="open">Open</option><option value="overdue">Overdue only</option></select></label><p>{{ completed }} of {{ items.length }} sample records marked done.</p><ol class="care-list"><li v-for="item in visible" :key="item.id"><div class="care-dot" aria-hidden="true"></div><div class="care-body"><h4>{{ item.title }}</h4><p><span class="care-status" :class="status(item).toLowerCase().replace(' ','-')">{{ status(item) }}</span></p><p>Due <time :datetime="item.due">{{ item.due }}</time><template v-if="item.completed"><br>Marked done <time :datetime="item.completed">{{ item.completed }}</time></template></p><button type="button" :aria-label="(item.completed?'Undo done: ':'Mark done: ')+item.title" @click="toggle(item)">{{ item.completed?'Undo done':'Mark done locally' }}</button></div></li></ol><p v-if="!visible.length" class="care-empty">No matching sample records. Choose All to see every record.</p><p role="status">{{ message }}</p><button type="button" @click="reset">Reset example</button></section>
</template>
<style scoped>
.care-timeline-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.care-timeline-demo h3{margin:0 0 12px}.care-timeline-demo label{display:flex;align-items:center;gap:12px;font-weight:650;flex-wrap:wrap}.care-timeline-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.care-timeline-demo button{padding:8px 10px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.care-timeline-demo :is(select,button):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.care-list{list-style:none!important;padding:0!important;margin:20px 0!important}.care-list li{display:grid;grid-template-columns:20px minmax(0,1fr);gap:16px;margin:0!important;position:relative;padding-bottom:20px}.care-list li:not(:last-child):before{content:'';position:absolute;top:14px;bottom:0;left:7px;width:2px;background:var(--vp-c-divider)}.care-dot{margin-top:5px;width:12px;height:12px;border:2px solid var(--vp-c-brand-1);border-radius:50%;background:var(--vp-c-bg);z-index:1}.care-body{padding:14px;border:1px solid var(--vp-c-divider);border-radius:10px;min-width:0;overflow-wrap:anywhere;animation:care-entry .18s ease-out}.care-body h4{margin:0;font-size:15px}.care-body p{font-size:13px;margin:8px 0}.care-status{display:inline-block;padding:3px 8px;border-radius:6px;background:var(--vp-c-bg-soft);font-weight:650}.care-status.done{background:#e3f4ea;color:#11643b}.care-status.overdue{background:#fde8ea;color:#a52432}.care-status.due-today{background:#fff0c2;color:#624600}.care-empty{padding:12px;background:var(--vp-c-bg-soft)}@keyframes care-entry{from{opacity:0;transform:translateX(4px)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){.care-body{animation:none}}
</style>
